// eslint-rules/no-alert-call.js
export default {
    meta: {
        type: "problem",
        docs: { description: "alert() chaqiruvini taqiqlaydi" },
        fixable: "code",
        messages: { noAlert: "alert() o'rniga showToast() ishlating" },
    },
    create(context) {
        return {
            CallExpression(node) {                 // har bir chaqiruv tuguni
                if (node.callee.type === "Identifier" && node.callee.name === "alert") {
                    context.report({
                        node,
                        messageId: "noAlert",
                        fix: (fixer) => fixer.replaceText(node.callee, "showToast"),
                    });
                }
            },
        };
    },
};

// @ts-check

/**
 * @typedef {Object} CartItem
 * @property {string} name
 * @property {number} price  - so'mda
 * @property {number} [qty]  - ixtiyoriy, sukut 1
 */

/**
 * Savat summasini hisoblaydi.
 * @param {CartItem[]} items
 * @param {{ discount?: number }} [options]
 * @returns {number}
 */
export function cartTotal(items, options = {}) {
    const sum = items.reduce((acc, it) => acc + it.price * (it.qty ?? 1), 0);
    return sum - sum * (options.discount ?? 0);
}

cartTotal([{ name: "Non", price: "5000" }]);
