    { id: "eqeqeq", severity: "error", re: /[^=!]==(?!=)/g, shift: 1, message: "Expected '===' and instead saw '=='" },
    { id: "no-debugger", severity: "error", re: /\bdebugger\b/g, message: "Unexpected 'debugger' statement" },
