// 3: if (x) { eval(code); }
const id = (name) => ({ type: "Identifier", name });
const call = (line, column, callee, args) => ({
    type: "ExpressionStatement",
    expression: { type: "CallExpression", loc: { start: { line, column } }, callee, arguments: args },
});
const ast = {
    type: "Program",
    body: [
        call(1, 0, id("eval"), [{ type: "Literal", value: "2 + 2" }]),
        call(2, 0, { type: "MemberExpression", object: id("console"), property: id("log") }, [id("user")]),
        { type: "IfStatement", test: id("x"), consequent: { type: "BlockStatement", body: [call(3, 9, id("eval"), [id("code")])] } },
    ],
};

const rule = {
    meta: { messages: { noEval: "eval() xavfli: satrdagi kodni bajarmang" } },
    create(context) {
        return {
            CallExpression(node) {
                if (node.callee.type === "Identifier" && node.callee.name === "eval") {
                    context.report({ node, messageId: "noEval" });
                }
            },
        };
    },
};

function lint(tree, ruleId, ruleDef) {
    const reports = [];
    const context = {
        report: ({ node, messageId }) =>
            reports.push({ ...node.loc.start, message: ruleDef.meta.messages[messageId], ruleId }),
    };
    const visitors = ruleDef.create(context);
    let visited = 0;
    (function walk(node) {
        if (!node || typeof node.type !== "string") return;
        visited++;
        visitors[node.type]?.(node);
        for (const value of Object.values(node)) {
            if (Array.isArray(value)) value.forEach(walk);
            else if (value && typeof value === "object") walk(value);
        }
    })(tree);
    return { reports, visited };
}

const { reports, visited } = lint(ast, "local/no-eval", rule);
for (const r of reports) console.log(`${r.line}:${r.column + 1}  error  ${r.message}  ${r.ruleId}`);
console.log(`Ko'rilgan tugunlar: ${visited}`);

