const config = { indent_style: "space", indent_size: 4, end_of_line: "lf", insert_final_newline: true, trim_trailing_whitespace: true };

function check(text) {
    const issues = [];
    if (config.end_of_line === "lf" && text.includes("\r\n")) issues.push("CRLF qator oxiri (LF kerak)");
    text.replace(/\r\n/g, "\n").split("\n").forEach((line, i) => {
        if (config.trim_trailing_whitespace && /[ \t]+$/.test(line)) issues.push(`${i + 1}-qator: oxirida bo'shliq`);
        if (config.indent_style === "space" && /^\t/.test(line)) issues.push(`${i + 1}-qator: tab bilan chekinish`);
    });
    if (config.insert_final_newline && !text.endsWith("\n")) issues.push("fayl oxirida yangi qator yo'q");
    return issues;
}

function fix(text) {
    const lines = text.replace(/\r\n/g, "\n").split("\n").map((line) => line
        .replace(/[ \t]+$/, "")
        .replace(/^\t+/, (tabs) => " ".repeat(tabs.length * config.indent_size)));
    const out = lines.join("\n");
    return out.endsWith("\n") ? out : `${out}\n`;
}

