    const code = fn.toString()
        .replace(/\/\/.*$/gm, "")                          // izohlar
        .replace(/(["'`])(?:\\.|(?!\1).)*\1/g, "S");          // satrlar
    const points = code.match(/\bif\b|\bfor\b|\bwhile\b|\bcase\b|\bcatch\b|&&|\|\||\?\?|\?(?![.?])/g) ?? [];
    return 1 + points.length;
}

