function shippingComplex(order) {
    let cost = 25000;
    if (order.total > 500000) cost = 0;
    else if (order.region === "Toshkent" && order.express) cost = 40000;
    else if (order.region === "Toshkent" || order.pickup) cost = 15000;
    for (const item of order.items) {
        if (item.heavy) cost += 10000;
    }
    switch (order.coupon) {
        case "FREE": cost = 0; break;
        case "HALF": cost /= 2; break;
    }
    return Math.max(cost, order.minCost ?? 0);
}

