class FakeClock {
    now = 0;
    #timers = [];
    #nextId = 1;
    setTimeout = (fn, ms) => {
        const id = this.#nextId++;
        this.#timers.push({ id, fn, at: this.now + ms });
        return id;
    };
    clearTimeout = (id) => {
        this.#timers = this.#timers.filter((t) => t.id !== id);
    };
    tick(ms) {
        const end = this.now + ms;
        for (;;) {
            const due = this.#timers.filter((t) => t.at <= end).sort((a, b) => a.at - b.at)[0];
            if (!due) break;
            this.now = due.at;
            this.clearTimeout(due.id);
            due.fn();
        }
        this.now = end;
    }
}

function debounce(fn, ms, timers) {
    let id;
    return (...args) => {
        timers.clearTimeout(id);
        id = timers.setTimeout(() => fn(...args), ms);
    };
}

const clock = new FakeClock();
const calls = [];
const search = debounce((query) => calls.push(`${query}@${clock.now}`), 300, clock);

search("j");
clock.tick(100);
search("js");
clock.tick(100);
search("jst");
clock.tick(299);
assert.deepEqual(calls, []); // hali erta
clock.tick(1);
assert.deepEqual(calls, ["jst@500"]);
console.log(calls);

