function createRng(seed) {
    return () => {
        seed = (seed * 1664525 + 1013904223) % 2 ** 32;
        return seed / 2 ** 32;
    };
}

function insertionSort(arr) {
    const copy = [...arr];
    for (let i = 1; i < copy.length; i++) {
        for (let j = i; j > 0 && copy[j - 1] > copy[j]; j--) {
            [copy[j - 1], copy[j]] = [copy[j], copy[j - 1]];
        }
    }
    return copy;
}

const rng = createRng(2026);
let checked = 0;
for (let run = 0; run < 200; run++) {
    const input = Array.from({ length: Math.floor(rng() * 20) }, () => Math.floor(rng() * 100) - 50);
    const output = insertionSort(input);
    // Xossalar: uzunlik saqlanadi, tartiblangan, ishonchli sort bilan mos
    assert.equal(output.length, input.length);
    assert.ok(output.every((x, i) => i === 0 || output[i - 1] <= x));
    assert.deepEqual(output, input.toSorted((a, b) => a - b));
    checked++;
}
console.log(`${checked} ta tasodifiy massivda barcha xossalar bajarildi`);

