import assert from "node:assert/strict";

async function retry(fn, { attempts = 3, baseDelay = 100, sleep }) {
    let lastError;
    for (let i = 0; i < attempts; i++) {
        try {
            return await fn(i + 1);
        } catch (err) {
            lastError = err;
            if (i < attempts - 1) await sleep(baseDelay * 2 ** i);
        }
    }
    throw new Error(`${attempts} urinishdan keyin ham muvaffaqiyatsiz`, { cause: lastError });
}

const delays = [];
const fakeSleep = async (ms) => {
    delays.push(ms); // haqiqatan kutmaymiz
};

// 1-holat: uchinchi urinishda muvaffaqiyat
const flaky = async (attempt) => {
    if (attempt < 3) throw new Error(`tarmoq xatosi #${attempt}`);
    return "ok";
};
assert.equal(await retry(flaky, { sleep: fakeSleep }), "ok");
assert.deepEqual(delays, [100, 200]);

// 2-holat: hamma urinish muvaffaqiyatsiz
delays.length = 0;
const broken = async (attempt) => {
    throw new Error(`timeout #${attempt}`);
};
await assert.rejects(retry(broken, { attempts: 4, sleep: fakeSleep }), (err) => {
    assert.match(err.message, /4 urinishdan/);
    assert.equal(err.cause.message, "timeout #4");
    return true;
});
assert.deepEqual(delays, [100, 200, 400]);
console.log("retry: kechikishlar", delays.join(", "), "— kutmasdan tekshirildi");

