async function olch(nom, fn) {
    const boshi = performance.now();
    try {
        return { nom, natija: await fn(), ms: performance.now() - boshi };
    } catch (xato) {
        return { nom, xato: xato.message, ms: performance.now() - boshi };
    }
}

