import { setImmediate as navbat } from "node:timers/promises";

async function sinov(navbatBer) {
    const log = [];
    const ish = (async () => {
        for (let i = 1; i <= 3; i++) {
            let s = 0;
            for (let j = 0; j < 1e5; j++) s += j;    // bitta bo'lak
            log.push(`bo'lak${i}`);
            if (navbatBer) await navbat();
        }
    })();
    setImmediate(() => log.push("so'rov"));       // shu orada kelgan so'rov
    await ish;
    await navbat();
    await navbat();
    return log.join(" → ");
}

console.log("navbatsiz:    ", await sinov(false));
console.log("navbat bilan: ", await sinov(true));

function benchmark(fn, { isitish = 50, takror = 200 } = {}) {
    for (let i = 0; i < isitish; i++) fn();          // JIT optimallashtirib olsin
    const vaqtlar = [];
    for (let i = 0; i < takror; i++) {
        const t = performance.now();
        fn();
        vaqtlar.push(performance.now() - t);
    }
    vaqtlar.sort((a, b) => a - b);
    return { median: vaqtlar[Math.floor(takror / 2)], p95: vaqtlar[Math.floor(takror * 0.95)] };
}

const royxat = Array.from({ length: 5000 }, (_, i) => i);
const toplam = new Set(royxat);
const qidiruv = Array.from({ length: 500 }, (_, i) => i * 10);

let sink = 0;   // natija ishlatiladi — optimallashtiruvchi kodni tashlab yubormaydi
const massiv = benchmark(() => { for (const q of qidiruv) if (royxat.includes(q)) sink++; });
const set = benchmark(() => { for (const q of qidiruv) if (toplam.has(q)) sink++; });

console.log("Set.has tezroq (median):", set.median < massiv.median);
console.log("p95 >= median:", massiv.p95 >= massiv.median && set.p95 >= set.median);
console.log("sink:", sink);

function takrorlarSodda(arr) {
    let amallar = 0;
    const natija = new Set();
    for (let i = 0; i < arr.length; i++) {
        for (let j = 0; j < i; j++) {
            amallar++;
            if (arr[i] === arr[j]) { natija.add(arr[i]); break; }
        }
    }
    return { natija: [...natija], amallar };
}

function takrorlarSet(arr) {
    let amallar = 0;
    const korilgan = new Set();
    const natija = new Set();
    for (const x of arr) {
        amallar++;
        if (korilgan.has(x)) natija.add(x);
        else korilgan.add(x);
    }
    return { natija: [...natija], amallar };
}

for (const n of [10, 100, 1000]) {
    const arr = Array.from({ length: n }, (_, i) => i % (n - 1));   // oxirgi element takror
    const a = takrorlarSodda(arr);
    const b = takrorlarSet(arr);
    const bir = String(a.natija) === String(b.natija);
    console.log(`n=${n}: sodda ${a.amallar}, Set ${b.amallar}, natija bir xil: ${bir}`);
}

