function sekinniLogla(nom, fn, { chegara = 100, soat = () => performance.now(), log = console.log } = {}) {
    return async (...args) => {
        const boshi = soat();
        try {
            return await fn(...args);
        } finally {
            const ms = soat() - boshi;
            if (ms > chegara) log(`SEKIN ${nom}: ${ms} ms (chegara ${chegara})`, { args });
        }
    };
}

