import { createServer } from "node:http";

const kut = (ms) => new Promise((r) => setTimeout(r, ms));

const server = createServer(async (req, res) => {
    const t0 = performance.now();
    await kut(20);                                   // db
    const t1 = performance.now();
    await kut(5);                                    // shablon
    const t2 = performance.now();
    const dur = (a, b) => (b - a).toFixed(1);
    res.setHeader("Server-Timing", `db;dur=${dur(t0, t1)}, render;dur=${dur(t1, t2)};desc="HTML"`);
    res.end("ok");
});

server.listen(0, async () => {
    const javob = await fetch(`http://127.0.0.1:${server.address().port}/`);
    const sarlavha = javob.headers.get("server-timing");
    console.log("status:", javob.status, await javob.text());
    console.log("bosqichlar:", sarlavha.split(",").map((q) => q.trim().split(";")[0]));
    console.log("db >= 15 ms:", Number(sarlavha.match(/db;dur=([\d.]+)/)[1]) >= 15);
    server.close();
    server.closeAllConnections();
});

